package api

import "time"

// Help requests are shared within their verified workspace and visibility class.
// Context is generated by the server; input/result payloads and prices are absent.
type ProductHelpCreate struct {
	ID          string `json:"id"`
	Kind        string `json:"kind"`
	Feature     string `json:"feature,omitempty"`
	OperationID string `json:"operation_id,omitempty"`
	Message     string `json:"message"`
}

type ProductHelpContext struct {
	ObservedAt     time.Time                    `json:"observed_at"`
	Revision       string                       `json:"revision"`
	PolicyRevision string                       `json:"policy_revision"`
	Period         string                       `json:"period"`
	Plan           string                       `json:"plan"`
	Suspended      bool                         `json:"suspended"`
	Reason         string                       `json:"reason"`
	Feature        string                       `json:"feature,omitempty"`
	Usage          *ProductFeatureUsageGuidance `json:"usage,omitempty"`
	ResetsAt       *time.Time                   `json:"resets_at,omitempty"`
}

type ProductHelpRequest struct {
	AccountID string             `json:"account_id"`
	AppID     string             `json:"app_id"`
	TenantID  string             `json:"tenant_id"`
	Request   ProductHelpCreate  `json:"request"`
	Context   ProductHelpContext `json:"context"`
	Status    string             `json:"status"`
	Response  string             `json:"response"`
	Version   int64              `json:"version"`
	CreatedAt time.Time          `json:"created_at"`
	UpdatedAt time.Time          `json:"updated_at"`
}

type ProductHelpPage struct {
	Requests   []ProductHelpRequest `json:"requests"`
	NextCursor string               `json:"next_cursor,omitempty"`
	ObservedAt time.Time            `json:"observed_at"`
}

type ProductHelpUpdate struct {
	ExpectedVersion int64  `json:"expected_version"`
	Status          string `json:"status"`
	Response        string `json:"response"`
}
